mapper.select:
SELECT user_id as userId, phone, password , real_name as realName, role, status,kyc_status
FROM sys_user
WHERE phone = #{phone}

mapper.update:
UPDATE sys_user
SET account_balance = account_balance + #{amount}, update_time = CURRENT_TIMESTAMP
WHERE user_id = #{userId}

mapper.select:
SELECT su.user_id AS userId, su.phone, CASE WHEN su.kyc_status = 1 THEN COALESCE(ui.user_real_name, su.real_name) ELSE '' END AS name, su.real_name AS nickname, CASE su.kyc_status WHEN 1 THEN 'verified' WHEN 2 THEN 'verifying' ELSE 'unverified' END AS verifyStatus, su.status, ucs.credit_score AS creditScore, su.create_time AS registerTime, su.update_time AS lastLoginTime FROM sys_user su LEFT JOIN user_credit_score ucs ON su.user_id = ucs.user_id LEFT JOIN user_identity ui ON su.user_id = ui.user_id WHERE su.role != 'admin'
AND su.phone LIKE CONCAT('%', #{phone}, '%')
AND su.real_name LIKE CONCAT('%', #{name}, '%')
AND su.create_time >= #{startDate}
AND su.create_time <= CONCAT(#{endDate}, ' 23:59:59')
AND su.kyc_status = #{kycStatus}
ORDER BY
su.create_time ucs.credit_score su.create_time
ASC DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1) FROM sys_user su WHERE su.role != 'admin'
AND su.phone LIKE CONCAT('%', #{phone}, '%')
AND su.real_name LIKE CONCAT('%', #{name}, '%')
AND su.create_time >= #{startDate}
AND su.create_time <= CONCAT(#{endDate}, ' 23:59:59')
AND su.kyc_status = #{kycStatus}
